/** Options which are added to the TableColumn interface if this plugin is enabled. */
export interface UseColumnSizesColumnOptions {
    /** Defines the ratio of a column width in reference to the width of the entire table. */
    ratioWidth?: number;
    /**
     * Sets the column into an autoSizing mode.
     * This mode sets the column size based on the initially visible
     * cells and adjusts the width accordingly.
     */
    autoWidth?: boolean;
    /**
     * This is the maximum column width allowed for a given column during the autoWidth
     * calculation. For example if the column content would have a width of 2000 pixels
     * and maxAutoWidth is given as 600 then the column width value will initially be
     * limited at 600. If resizable is enabled, it is still allowed to resize beyond
     * maxAutoWidth (as opposed to maxWidth).
     */
    maxAutoWidth?: number;
}
/** Extension interface for the ColumnInterfaces when useColumnSizes plugin is used. */
export interface UseColumnSizesColumnInstance {
    /** Defines the ratio of a column width in relation to the width of the entire table. */
    ratioWidth?: number;
    /**
     * Sets the column into an autoSizing mode.
     * This mode sets the column size based on the initially visible
     * cells and adjusts the width accordingly.
     */
    autoWidth?: boolean;
    /**
     * This is the maximum column width allowed for a given column during the autoWidth
     * calculation. For example if the column content would have a width of 2000 pixels
     * and maxAutoWidth is given as 600 then the column width value will initially be
     * limited at 600. If resizable is enabled, it is still allowed to resize beyond
     * maxAutoWidth (as opposed to maxWidth).
     */
    maxAutoWidth?: number;
}
/** Extension interface for the TableState when the useColumnSizes plugin is used. */
export interface UseColumnSizesState {
    /** CSS grid template definitions per header row. */
    columnGridTemplate?: string;
    /**
     * Holds the recorded width of each cell within a column in order to determine its desired
     * width.
     */
    cellWidthsByColumn?: Record<string, number>;
    /** Mutable flag on the state used in order to flag when the rendering is finished and dispatch a doneMeasuring action. */
    isMeasuringInProgress?: boolean;
}
